materialized_view = COLLECT.materialized_view
dp = COLLECT


@materialized_view(
    name=_n("journey_clinical.form_swallowing_screen"),
    refresh_policy="auto",
)
def form_swallowing_screen():
    # Build the declared dataset: Swallowing screen: one row per form instance with configured
    # questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["swallowing_screen"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("swallowing_screen")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("swallow_screen_complete", "CODED"),
        *_single_aggregations("swallow_screen_calc", "NUMERIC"),
        *_single_aggregations("teaspoon_of_water_problem_encountered", "CODED"),
        *_single_aggregations("sip_of_water_problem_encountered", "CODED"),
        *_single_aggregations("glass_of_water_problem_encountered", "CODED"),
        *_multi_aggregations(cfg, "passed_swallow_screen_recommendations", "CODED"),
        *_multi_aggregations(cfg, "failed_screen_recommendations", "CODED"),
        *_multi_aggregations(cfg, "failed_swallow_screen_recommendations", "CODED"),
        *_multi_aggregations(cfg, "item_1st_teaspoon_of_water_problem", "CODED"),
        *_multi_aggregations(cfg, "give_sip_of_water_problem", "CODED"),
        *_multi_aggregations(cfg, "give_glass_water_problem", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")


